import { db } from '@shared/database';

export interface PermissionCheckOptions {
  userId: string;
  applicationId: string;
  permissionSlug: string;
}

export async function hasPermission({
  userId,
  applicationId,
  permissionSlug,
}: PermissionCheckOptions): Promise<boolean> {
  // Check if user has direct permission
  const directPermission = await db.userPermission.findFirst({
    where: {
      userId,
      permission: {
        slug: permissionSlug,
        applicationId,
      },
      granted: true,
    },
  });

  if (directPermission) {
    return true;
  }

  // Check if user has permission through a role
  const rolePermission = await db.userRole.findFirst({
    where: {
      userId,
      role: {
        applicationId,
        rolePermissions: {
          some: {
            permission: {
              slug: permissionSlug,
              applicationId,
            },
          },
        },
      },
    },
  });

  return !!rolePermission;
}

export async function hasAnyPermission(
  userId: string,
  applicationId: string,
  permissionSlugs: string[]
): Promise<boolean> {
  const checks = await Promise.all(
    permissionSlugs.map((slug) =>
      hasPermission({ userId, applicationId, permissionSlug: slug })
    )
  );
  return checks.some((result) => result === true);
}

export async function hasAllPermissions(
  userId: string,
  applicationId: string,
  permissionSlugs: string[]
): Promise<boolean> {
  const checks = await Promise.all(
    permissionSlugs.map((slug) =>
      hasPermission({ userId, applicationId, permissionSlug: slug })
    )
  );
  return checks.every((result) => result === true);
}
